-- Fresh profile of Delta Chat core v2.69.0, generated by scripts/backup-schema.py.
CREATE TABLE "acpeerstates" (
             id INTEGER PRIMARY KEY,
             addr TEXT DEFAULT '' COLLATE NOCASE,
             last_seen INTEGER DEFAULT 0,
             last_seen_autocrypt INTEGER DEFAULT 0,
             public_key,
             prefer_encrypted INTEGER DEFAULT 0,
             gossip_timestamp INTEGER DEFAULT 0,
             gossip_key,
             public_key_fingerprint TEXT DEFAULT '',
             gossip_key_fingerprint TEXT DEFAULT '',
             verified_key,
             verified_key_fingerprint TEXT DEFAULT '', verifier TEXT DEFAULT '', secondary_verified_key, secondary_verified_key_fingerprint TEXT DEFAULT '', secondary_verifier TEXT DEFAULT '', backward_verified_key_id -- What we think the contact has as our verified key
               INTEGER,
             UNIQUE (addr) -- Only one peerstate per address
             );
CREATE TABLE available_post_msgs (
                rfc724_mid TEXT PRIMARY KEY
            ) STRICT;
CREATE TABLE bobstate (
                   id INTEGER PRIMARY KEY AUTOINCREMENT,
                   invite TEXT NOT NULL,
                   next_step INTEGER NOT NULL,
                   chat_id INTEGER NOT NULL
            );
CREATE TABLE broadcast_secrets(
                chat_id INTEGER PRIMARY KEY NOT NULL,
                secret TEXT NOT NULL
            ) STRICT;
CREATE TABLE broadcasted_reactions (
                msg_id INTEGER NOT NULL DEFAULT 0,
                reaction TEXT NOT NULL DEFAULT '',
                count INTEGER NOT NULL DEFAULT 0,
                FOREIGN KEY(msg_id) REFERENCES msgs(id) ON DELETE CASCADE -- delete reactions when message is deleted
            ) STRICT;
CREATE TABLE chats (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    type INTEGER DEFAULT 0,
    name TEXT DEFAULT '',
    draft_timestamp INTEGER DEFAULT 0,
    draft_txt TEXT DEFAULT '',
    blocked INTEGER DEFAULT 0,
    grpid TEXT DEFAULT '',
    param TEXT DEFAULT '',
    archived INTEGER DEFAULT 0,
    gossiped_timestamp INTEGER DEFAULT 0, -- deprecated 2025-04-08, replaced with gossiped_timestamp table
    locations_send_begin INTEGER DEFAULT 0,
    locations_send_until INTEGER DEFAULT 0,
    locations_last_sent INTEGER DEFAULT 0,
    created_timestamp INTEGER DEFAULT 0,
    muted_until INTEGER DEFAULT 0,
    ephemeral_timer INTEGER
, protected INTEGER DEFAULT 0, name_normalized TEXT);
