CREATE TABLE "chats_contacts" (chat_id INTEGER, contact_id INTEGER, add_timestamp NOT NULL DEFAULT 0, remove_timestamp NOT NULL DEFAULT 0, UNIQUE(chat_id, contact_id));
CREATE TABLE chats_descriptions (chat_id INTEGER PRIMARY KEY AUTOINCREMENT, description TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE "config" (
               id INTEGER PRIMARY KEY,
               keyname TEXT UNIQUE,
               value TEXT NOT NULL
             );
INSERT INTO "config" VALUES(1,'dbversion','170');
INSERT INTO "config" VALUES(2,'keyupdate_baseline','');
CREATE TABLE connection_history (
                host TEXT NOT NULL, -- server hostname
                port INTEGER NOT NULL, -- server port
                alpn TEXT NOT NULL, -- ALPN such as smtp or imap
                addr TEXT NOT NULL, -- IP address
                timestamp INTEGER NOT NULL, -- timestamp of the most recent successful connection
                UNIQUE (host, port, alpn, addr)
            ) STRICT;
CREATE TABLE contacts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT DEFAULT '',
    addr TEXT DEFAULT '' COLLATE NOCASE,
    origin INTEGER DEFAULT 0,
    blocked INTEGER DEFAULT 0,
    last_seen INTEGER DEFAULT 0,
    param TEXT DEFAULT '',
    authname TEXT DEFAULT '',
    selfavatar_sent INTEGER DEFAULT 0
, status TEXT DEFAULT '', is_bot INTEGER NOT NULL DEFAULT 0, fingerprint TEXT NOT NULL DEFAULT '', verifier INTEGER NOT NULL DEFAULT 0, name_normalized TEXT);
